// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;

/**
 * Bounded memoization over any deterministic unary predicate fragment (fragment-fusion M6, the Velox dictionary-peeling
 * move): the wrapped predicate is evaluated once per distinct id and its verdict cached in accept/reject id sets. Memo
 * state lives in {@link FragmentBinding#state} (snapshot-scoped, never crosses transactions) via {@link MemoState}; the
 * sets are size-bounded (skew protection — a pathological distinct stream must not grow unbounded state), and the state
 * self-abandons when observed hit rates show near-1:1 distinct/row ratios, where memoization is pure overhead. Parallel
 * forks copy their sets explicitly.
 */
public final class MemoizedPredicateFragment implements LongPredicateFragment {

	private final LongPredicateFragment inner;

	public MemoizedPredicateFragment(LongPredicateFragment inner) {
		this.inner = inner;
	}

	/** Snapshot-scoped memo sets; install into {@link FragmentBinding#state} at bind time. */
	public static final class MemoState implements FragmentBinding.ForkableFragmentState {
		private static final int MIN_OBSERVATIONS = 256;
		private static final double ABANDON_BELOW_HIT_RATE = 0.10;

		final KernelRuntime.LongHashSet accepted;
		final KernelRuntime.LongHashSet rejected;
		final int maxEntries;
		long hits;
		long misses;
		boolean abandoned;

		public MemoState(int expected, int maxEntries) {
			this.accepted = new KernelRuntime.LongHashSet(expected);
			this.rejected = new KernelRuntime.LongHashSet(expected);
			this.maxEntries = maxEntries;
		}

		private MemoState(MemoState original) {
			this.accepted = new KernelRuntime.LongHashSet(Math.max(16, original.accepted.size()));
			this.rejected = new KernelRuntime.LongHashSet(Math.max(16, original.rejected.size()));
			this.accepted.addAll(original.accepted);
			this.rejected.addAll(original.rejected);
			this.maxEntries = original.maxEntries;
			this.hits = original.hits;
			this.misses = original.misses;
			this.abandoned = original.abandoned;
		}

		long entries() {
			return accepted.size() + rejected.size();
		}

		public long hits() {
			return hits;
		}

		public long misses() {
			return misses;
		}

		public boolean abandoned() {
			return abandoned;
		}

		private void observeMiss() {
			misses++;
			maybeAbandon();
		}

		private void maybeAbandon() {
			long observations = hits + misses;
			if (!abandoned && observations >= MIN_OBSERVATIONS
					&& (double) hits / observations < ABANDON_BELOW_HIT_RATE) {
				abandoned = true;
			}
		}

		@Override
		public Object forkForParallelWorker() {
			return new MemoState(this);
		}
	}

	@Override
	public PredicateStatus test(long a0, long a1, long a2, FragmentBinding binding) {
		if (!(binding.state instanceof MemoState memo) || memo.abandoned) {
			return inner.test(a0, a1, a2, binding);
		}
		if (a0 == -1L) {
			// unbound has one verdict; no reason to spend a set entry on it
			return inner.test(a0, a1, a2, binding);
		}
		if (memo.accepted.contains(a0)) {
			memo.hits++;
			FragmentTelemetry.MEMO_HITS.increment();
			return PredicateStatus.TRUE;
		}
		if (memo.rejected.contains(a0)) {
			memo.hits++;
			FragmentTelemetry.MEMO_HITS.increment();
			return PredicateStatus.FALSE;
		}
		FragmentTelemetry.MEMO_MISSES.increment();
		memo.observeMiss();
		PredicateStatus status = inner.test(a0, a1, a2, binding);
		if (status == PredicateStatus.ESCAPE) {
			// resolve through the exact tier ONCE per distinct id — this is the whole point of the memo form
			boolean accepted = binding.escapeToExact(a0, a1, a2);
			remember(memo, a0, accepted);
			return accepted ? PredicateStatus.TRUE : PredicateStatus.FALSE;
		}
		if (status == PredicateStatus.TRUE || status == PredicateStatus.FALSE) {
			remember(memo, a0, status == PredicateStatus.TRUE);
		}
		return status;
	}

	private static void remember(MemoState memo, long id, boolean accepted) {
		if (memo.entries() >= memo.maxEntries) {
			return;
		}
		(accepted ? memo.accepted : memo.rejected).add(id);
	}
}
